/* Task destinations only; no changes to authorization or confirmation flows. */
.sf-owner .sf-work-lanes,
.sdh-customer-card .sdh-work-lanes { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 10px; margin-top: 14px; }
.sf-owner .sf-work-lane,
.sdh-customer-card .sdh-work-lane { min-width: 0; padding: 13px; border: 1px solid #e2e8f0; border-radius: 10px; background: #f8fafc; }
.sf-owner .sf-work-lane-owner,
.sdh-customer-card .sdh-work-lane-owner { background: #f5f8ff; border-color: #d9e5fc; }
.sf-owner .sf-work-lane-heading h3,
.sdh-customer-card .sdh-work-lane h4,
.sdh-receipt-next h4 { font-size: 14px; line-height: 21px; font-weight: 650; color: #263e60; }
.sf-owner .sf-work-lane-heading p { margin-top: 3px; font-size: 12px; line-height: 18px; color: #718098; }
.sf-owner .sf-work-lane .sf-owner-counts { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 0; }
.sf-owner .sf-work-lane .sf-owner-counts button { flex: 1; display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 44px; padding: 8px 12px; background: #fff; border-color: #dfe7f4; }
.sf-owner .sf-work-lane .sf-owner-counts span { font-size: 13px; line-height: 20px; }
.sf-owner .sf-work-lane .sf-owner-counts strong { margin: 0; font-size: 20px; line-height: 24px; font-variant-numeric: tabular-nums; }
.sf-owner .sf-work-lane-owner .sf-owner-counts :is(span,strong) { color: #245bd1; }
.sf-owner .sf-work-count-note { margin: 8px 0 12px; color: #8591a3; font-size: 11px; line-height: 18px; }
.sdh-customer-card .sdh-work-lane .sdh-queue-filters { margin: 9px 0 0; gap: 8px; }
.sdh-customer-card .sdh-work-lane .sdh-queue-filters button { flex: 1; min-height: 44px; justify-content: space-between; padding: 8px 12px; }
.sdh-customer-card .sdh-work-lane .sdh-queue-filters button span { font-size: 17px; line-height: 24px; }
.sdh-customer-card .sdh-queue-history { display: flex; align-items: center; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; margin: 14px 0; }
.sdh-customer-card .sdh-queue-history .sdh-queue-filters { margin: 0; }
.sdh-customer-card .sdh-queue-history p,
.sdh-receipt-next > p { font-size: 12px; line-height: 19px; color: #718098; }
.sdh-receipt-next { margin-top: 16px; padding-top: 14px; border-top: 1px solid #e5ebf4; }
.sdh-receipt-next .sdh-receipt-actions { margin-top: 10px; }
.sdh-receipt-next > p { margin-top: 9px; }
.sdh-receipt-next .sdh-receipt-actions > button { min-height: 40px; white-space: normal; height: auto; }
@media (max-width: 639px) {
  .sf-owner .sf-work-lanes,
  .sdh-customer-card .sdh-work-lanes { grid-template-columns: minmax(0, 1fr); gap: 8px; }
  .sf-owner .sf-work-lane,
  .sdh-customer-card .sdh-work-lane { padding: 12px; }
  .sf-owner .sf-work-lane .sf-owner-counts button { min-width: 0; padding: 9px 10px; }
  .sdh-customer-card .sdh-queue-history { align-items: flex-start; }
  .sdh-customer-card .sdh-queue-history p { width: 100%; }
  .sdh-receipt-next .sdh-receipt-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .sdh-receipt-next .sdh-receipt-actions > button { min-width: 0; min-height: 44px; padding-inline: 9px; line-height: 20px; }
  .sdh-receipt-next .sdh-receipt-actions > .sdh-note { grid-column: 1 / -1; }
}

export function dossierQualityHints(data: Pick<SalesDossier, 'enrichment' | 'summary' | 'insight'>): DossierQualityHint[] {
    const { enrichment, summary, insight } = data;
    const hints: DossierQualityHint[] = [];
    if (!enrichment.contacts.some(contact => hasText(contact.name))) {
        hints.push({ key: 'contact', kind: 'missing', label: enrichment.contacts.length ? '联系人姓名未填写' : '联系人未填写', detail: '沟通时补充联系人姓名与身份。' });
    }
    if (!hasText(enrichment.store_phone) && !enrichment.contacts.some(contact => hasText(contact.phone))) {
        hints.push({ key: 'phone', kind: 'missing', label: '联系电话未填写', detail: '补充门店或联系人号码，是否可拨打仍以联系保护与号码核验为准。' });
    }
    if (!enrichment.interest_product_ids.length) {
        hints.push({ key: 'interest', kind: 'to_understand', label: '意向产品待了解', detail: '尚未明确意向，可在沟通后补充，不必先猜选产品。' });
    }
    if (['follow_up', 'interested'].includes(insight.status)) {
        const missingStep = !hasText(summary.next_step);
        const missingTime = !hasText(summary.next_action_at || insight.next_follow_up_at);
        if (missingStep || missingTime) {
            hints.push({
                key: 'next_action', kind: 'to_arrange', label: '下一步待安排',
                detail: missingStep && missingTime ? '下一步内容与联系时间尚未填写。' : missingStep ? '下一步内容尚未填写，现有约定时间保持不变。' : '下一步已有记录，联系时间尚未约定。',
            });
        }
    }
    return hints;
}

export function ownerExceptionTaskHref(item: OwnerException) {
    const safe = followThroughHref(item.href);
    if (!safe)
        return '';
    if (item.kind === 'pending_access' && positiveId(item.customer_id))
        return `/customers?detail=${item.customer_id}&access=invite`;
    if (item.kind === 'pending_receipt' && positiveId(item.handoff_id))
        return `/sales-leads?view=handoffs&status=pending_payment&handoff=${item.handoff_id}&action=finance`;
    return safe;
}

export function salesHandoffCustomerHref(customerId: number, returnPath: string, invite = false) {
    if (!positiveId(customerId))
        return '';
    return buildReturnLink(`/customers?detail=${customerId}${invite ? '&access=invite' : ''}`, returnPath);
}

export function salesHandoffQueueHref(handoffId: number, returnPath: string, action?: 'finance' | 'ack') {
    if (!positiveId(handoffId))
        return '';
    return buildReturnLink(`/sales-leads?view=handoffs&handoff=${handoffId}${action ? `&action=${action}` : ''}`, returnPath);
}

export function salesHandoffReturnPath(currentPath: string, status: string, handoffId?: number | null) {
    const safe = getSafeInternalPath(currentPath, '/sales-leads?view=handoffs');
    const target = new URL(safe, 'https://t24-crm.local');
    target.searchParams.set('view', 'handoffs');
    target.searchParams.set('status', status);
    if (positiveId(handoffId ?? undefined))
        target.searchParams.set('handoff', String(handoffId));
    return `${target.pathname}${target.search}${target.hash}`;
}

