async (task: Task, phone: string) => {
    if (!canUseTask(task) || callSubmissionRef.current)
        throw new Error('当前任务尚未核对，请刷新今日队列后重试');
    if (task.lead.contact_protection?.can_contact === false)
        throw new Error(task.lead.contact_protection.reason || '请先查看商家档案中的联系保护与交接');
    const response = await invokeWithAuth({ url: `/api/v1/sales-leads/workbench/tasks/${task.task_id}/dial-started`, method: 'POST', data: { phone } });
    const confirmed = getCustomerDialValidation(response.data?.dial_phone || response.data?.phone || '', task.lead.country).e164;
    if (confirmed !== phone || (response.data?.lead_id != null && Number(response.data.lead_id) !== task.lead.id))
        throw new Error('拨号号码确认失败，尚未打开拨号器，请刷新资料后重试');
    if (task.task_status === 'completed') {
        const attemptId = response.data?.dial_attempt_id;
        if (!Number.isSafeInteger(attemptId) || attemptId <= 0)
            throw new Error('追加拨号记录未确认，请重试');
        supplementalAttemptRef.current = { taskId: task.task_id, leadId: task.lead.id, id: attemptId };
    }
}

